  'The Zavi fleet': 'The fleet',
  'Browse the fleet': 'Explore the fleet',
  'DUBAI, UNITED ARAB EMIRATES': 'Dubai, United Arab Emirates',
  Sports: 'Sports cars',
  SuperSport: 'Supercars',
  Convertible: 'Convertibles',
  Sedan: 'Sedans',
